#include <iostream>
#include <map>
#include <print>
#include <string>
#include <utility>

struct Item {
    static inline int alive = 0;
    std::string name;
    explicit Item(std::string n) : name(std::move(n)) {
        ++alive;
        std::println("создан {}", name);
    }
    ~Item() {
        --alive;
        std::println("удалён {}", name);
    }
};

struct Block {
    static inline int alive = 0;
    Item *object;
    long strong;
    long weak;
};

class Strong {
public:
    Strong() = default;
    explicit Strong(Item *p) : b_(new Block{p, 1, 0}) {
        ++Block::alive;
    }
    explicit Strong(Block *b) : b_(b) {
        ++b_->strong;
    }
    Strong(const Strong &o) : b_(o.b_) {
        if (b_) {
            ++b_->strong;
        }
    }
    Strong(Strong &&o) noexcept : b_(std::exchange(o.b_, nullptr)) {}
    Strong &operator=(Strong o) noexcept {
        std::swap(b_, o.b_);
        return *this;
    }
    ~Strong() {
        reset();
    }

    void reset() {
        if (b_) {
            if (--b_->strong == 0) {
                delete b_->object;
                b_->object = nullptr;
                if (b_->weak == 0) {
                    delete b_;
                    --Block::alive;
                }
            }
            b_ = nullptr;
        }
    }

    Block *block() const {
        return b_;
    }

private:
    Block *b_ = nullptr;
};

class Weak {
public:
    Weak() = default;
    explicit Weak(const Strong &s) : b_(s.block()) {
        if (b_) {
            ++b_->weak;
        }
    }
    Weak(const Weak &o) : b_(o.b_) {
        if (b_) {
            ++b_->weak;
        }
    }
    Weak(Weak &&o) noexcept : b_(std::exchange(o.b_, nullptr)) {}
    Weak &operator=(Weak o) noexcept {
        std::swap(b_, o.b_);
        return *this;
    }
    ~Weak() {
        reset();
    }

    void reset() {
        if (b_) {
            if (--b_->weak == 0 && b_->strong == 0) {
                delete b_;
                --Block::alive;
            }
            b_ = nullptr;
        }
    }

    bool expired() const {
        return !b_ || b_->strong == 0;
    }

    Strong lock() const {
        return expired() ? Strong() : Strong(b_);
    }

    const Item *peek() const {
        return expired() ? nullptr : b_->object;
    }

private:
    Block *b_ = nullptr;
};

template <class Map>
void reset_all(Map &m) {
    for (auto it = m.rbegin(); it != m.rend(); ++it) {
        it->second.reset();
    }
}

void stats() {
    std::println("объектов {}, блоков {}", Item::alive, Block::alive);
}

int main() {
    std::map<std::string, Strong> strong;
    std::map<std::string, Weak> weak;
    std::string command;
    while (std::cin >> command) {
        if (command == "stats") {
            stats();
            continue;
        }
        std::string a;
        std::cin >> a;
        if (command == "new") {
            std::string name;
            std::cin >> name;
            strong[a] = Strong(new Item(name));
        } else if (command == "watch") {
            std::string s;
            std::cin >> s;
            weak[a] = Weak(strong[s]);
        } else if (command == "lock") {
            std::string w;
            std::cin >> w;
            strong[a] = weak[w].lock();
        } else if (command == "reset") {
            strong[a].reset();
        } else if (command == "forget") {
            weak[a].reset();
        } else if (const Item *item = weak[a].peek()) {
            std::println("{}: жив {}", a, item->name);
        } else {
            std::println("{}: истёк", a);
        }
    }
    reset_all(strong);
    reset_all(weak);
    stats();
    return 0;
}

